command:
cat > /tmp/spacev_config.json << 'EOF'
{
  "spacev": {
    "engine": {
      "version": "5.2.1",
      "mode": "autonomous",
      "modules": {
        "sandbox": {
          "enabled": true,
          "provider": "celesto",
          "microvm": {
            "memory_mb": 2048,
            "cpu_cores": 2,
            "network": {
              "isolation": true,
              "allow_outbound": false
            }
          }
        },
        "assistant": {
          "persona": "cosmic-tier",
          "voice": {
            "enabled": true,
            "rate": 1.0,
            "pitch": 1.1
          }
        }
      }
    },
    "logging": {
      "level": "INFO",
      "file": "/var/log/spacev.log",
      "rotation": {
        "max_bytes": 10485760,
        "backup_count": 5
      }
    }
  }
}
EOF
python3 -m json.tool /tmp/spacev_config.json > /dev/null 2>&1 && echo "RESULT: VALID_JSON_SYNTAX" || echo "RESULT: INVALID_JSON_SYNTAX"
